steps.solutionCode:
const cards = document.querySelectorAll('.card');

const soldOutClass = 'is-soldout';

cards[1].classList.add(soldOutClass);

for (const card of document.querySelectorAll('.card')) {
  const stock = Number(card.querySelector('.card__stock').textContent);

  if (stock === 0) {
    card.classList.add('is-soldout');
  }
}
